// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * Workflow DSL v2 — TypeScript model of dsl/spec.json.
 *
 * A workflow definition has two halves:
 *   - `init`  — the template: which tasks it applies to (`condition`), the
 *               default projection over the task source (`apply.default`),
 *               the entry step (`start_id`), and the step templates.
 *   - `diff`  — an ordered rule set (ascending `priority`, first match per
 *               step wins within a priority tier) that reacts to step-state
 *               changes and mutates the instance (`internal`) or reaches out
 *               of it (`external`: email / agent).
 *
 * Resolution conventions from the spec:
 *   - MongoDB-style query documents are evaluated against object data or step
 *     state by the engine's matcher (engine/src/core/mongo.ts).
 *   - `prompt` vs `query`/`value` — anywhere both appear, the deterministic
 *     branch (`query`/`value`) is preferred; `prompt` is resolved through the
 *     pluggable PromptEvaluator and is a no-op offline.
 */

/** A MongoDB-style query document, e.g. { "department": "finance", "count": { "$gte": 3 } }. */
export type MongoExpr = Record<string, unknown>;

/**
 * The step-state vocabulary. These are LABELS ONLY — the engine attaches no
 * behavior to any particular value: it does not know that "completed" means
 * done, that "open" is resumable, or that "rejected" is terminal. It only
 * validates that a value is in this list and reports transitions to diff.
 *
 * All per-value behavior is authored in `diff` rules, which route on
 * transitions — { "step$state": { "$delta": { "before": "open", "after": "rejected" } } }
 * — and set any step property in response, including timestamps:
 *
 *   { "internal": { "scope": "self",
 *                   "set": { "completed_at": { "value": { "$delta": {} } } } } }
 *
 * The first entry is the default initial state for a step that does not
 * declare `state.default`.
 */
export const STEP_STATES = ['open', 'completed', 'rejected', 'escalated'] as const;
export type StepStateValue = (typeof STEP_STATES)[number];

/** Relative time offset used by due_on. */
export interface Delta {
  days?: number;
  hours?: number;
  minutes?: number;
}

/** Directory query for people: any subset of department / role, plus free-text AI context. */
export interface DirectoryQuery {
  department?: string;
  ai_context?: string;
  role?: string;
}

/**
 * Either/or resolution: exactly one of `prompt` (AI) or `query` (deterministic)
 * should be set; when both are present the engine prefers `query`.
 */
export interface OrResolution<Q = MongoExpr | DirectoryQuery> {
  $or: {
    prompt?: string;
    query?: Q;
  };
}

/**
 * Whether the actor must attach evidence when they move this step's state.
 * Enforced by the engine like `comments_required`: the request must carry an
 * `evidence` reference (a URI or document id — the artifact itself lives
 * outside the engine). Rule-driven transitions are exempt.
 */
export interface EvidenceRequiredSpec {
  default: boolean;
  /** Free-text criterion the evidence reviewer (human or AI) evaluates against. */
  evaluation_criterion?: string;
  /** Overrides `default` when it resolves truthy for the instance's task. */
  condition?: OrResolution;
  /**
   * Restrict the requirement to transitions INTO these states. Omit to demand
   * it on every state change. Declaring `["completed"]` is the usual intent:
   * substantiate finishing the work, but do not demand an artifact to reject
   * or escalate it.
   */
  required_on?: StepStateValue[];
}

/**
 * Whether the actor must record a comment when they move this step's state.
 * Enforced by the engine: a user-driven transition on a step with
 * `comments_required` true is refused (422) unless the request carries a
 * comment. Rule-driven transitions are exempt — automation has no author to
 * ask, and blocking it would deadlock the workflow.
 */
export interface CommentsRequiredSpec {
  default: boolean;
  /** Shown to the actor when a comment is demanded — say what a good one contains. */
  evaluation_criterion?: string;
  /** Overrides `default` when it resolves truthy for the instance's task. */
  condition?: OrResolution;
  /**
   * Restrict the requirement to transitions INTO these states. Omit to demand
   * a comment on every state change — e.g. `["completed", "rejected"]` asks
   * for reasoning on both decisions but not on picking the step back up.
   */
  required_on?: StepStateValue[];
}

export interface AssigneeSpec {
  /** Max number of assignees resolved from the condition (default 1). */
  limit?: number;
  condition: OrResolution<DirectoryQuery | MongoExpr>;
  /**
   * Exclude people who are no longer with the organisation
   * (`employment_status_active: false` on the directory record — the same field
   * the platform's person record carries). **Defaults to true**: presence is something you
   * consciously switch off, not something an author must remember to add, or a
   * plain `{role: "checker"}` query quietly hands work to whoever left.
   * Records with the field absent count as present.
   */
  require_active?: boolean;
  /**
   * Re-run the assignee query when the step enters one of these states, instead
   * of keeping whoever was resolved at init.
   *
   * Stickiness is right for a send-back — the maker who submitted should get
   * their own work back — and wrong when that person has since left. Because
   * only the author knows which they want, this is declared, not inferred.
   * `["open"]` is the usual choice: rework goes to someone present.
   *
   * A step also re-resolves when it is ACTIVATED (dormant → actionable) and its
   * current state is listed here. A dormant step's assignee was chosen at
   * attach, possibly long before the work reaches it, so re-resolving on
   * activation is what makes `strategy` and presence apply to it at all.
   */
  reresolve_on?: StepStateValue[];
  /**
   * How to choose among candidates the query returns, once `limit` is applied.
   *
   * - `first` (default) — directory order. Deterministic, and what the engine
   *   has always done, so existing workflows are unaffected.
   * - `least_loaded` — fewest open assigned steps across live instances. Ties
   *   break on directory order, so the result is still deterministic.
   * - `round_robin` — rotate through candidates per step template, so repeated
   *   instances of the same workflow spread across the team.
   *
   * Load counts only steps that are actionable (`status: true`) and not yet
   * closed: a dormant step is not work anybody is holding, and neither is a
   * finished one.
   */
  strategy?: AssigneeStrategy;
  /**
   * Resolve this step's assignee *relative to another step's holder*, instead
   * of by a directory query — the shape escalation actually has: "whoever
   * reviews this goes to the submitter's reporting manager".
   *
   * `from_step` names the step whose assignees to start from, or `from_query`
   * a directory query identifying the anchor; `levels` walks that many rungs of
   * the reporting matrix (default 1) in `direction`: `up` to their managers,
   * `down` to their reportees. The matrix is scoped by the instance's
   * `task.business_unit`.
   *
   * Resolves when the step is ENTERED (activated, or on a `reresolve_on`
   * state), never at attach: at attach the step it points at may not have its
   * own holder yet, and the answer would be stale by the time the work
   * arrives. Falls back to `condition` when the chain runs out — a step with
   * nobody above it must not become unassignable.
   */
  relative?: RelativeAssignee;
}

/**
 * Where a relative walk starts. Exactly one anchor must be given — the two are
 * different questions ("relative to whoever holds that step" vs "relative to
 * whoever the directory says owns this"), and accepting both would leave the
 * precedence between them silently up to the engine.
 */
export interface RelativeAssignee {
  /** Step id whose assignees are the starting point. */
  from_step?: string;
  /**
   * Directory query whose hits are the starting point, for anchoring on an org
   * position rather than on a step's holder: "one level below the LT member who
   * owns this division" is `from_query: {role: 'lt', division: {$object:
   * 'division'}}` with `direction: 'down'`.
   *
   * Supports the `{"$object": "<path>"}` token, so the anchor can depend on the
   * object the instance is attached to. Unlike `from_step`, the anchor need not
   * hold any step in this workflow.
   */
  from_query?: DirectoryQuery;
  /**
   * `up` (default) walks to managers — escalation. `down` walks to reportees,
   * which is how "one level below <person>" is expressed.
   *
   * With `from_step`, `down` walks from a step's holder. With `from_query` it
   * walks from whoever the directory identifies, which is how an org position
   * is anchored without modelling a person→org-node ownership edge: the
   * directory record carries the position, and the matrix carries the rungs.
   */
  direction?: 'up' | 'down';
  /** Rungs to walk; 1 = that person's managers (or reportees). */
  levels?: number;
}

export type AssigneeStrategy = 'first' | 'least_loaded' | 'round_robin';

/**
 * Policy for a user-driven due-date extension on a step. Declaring it turns a
 * `due_on` PATCH on that step from a free reschedule into a bounded, one-shot
 * extension: allowed only near the due date, capped in length, and (by
 * default) usable once — the engine reads the step's own history to know
 * whether it has already been spent. Omit the block entirely to keep the
 * permissive default (any writer may set `due_on` freely).
 */
export interface DueOnExtensionSpec {
  /** Furthest the new date may sit past the current one, in days (default 15). */
  max_days?: number;
  /** How many days before the due date the extension window opens (default 3). */
  window_days?: number;
  /** One extension per step (default true). */
  once?: boolean;
}

/** One step template inside `init.steps`. */
export interface StepTemplate {
  id: string;
  title: string;
  description?: string;
  /** Due date as an offset from instance creation. */
  due_on?: { $delta: Delta };
  /** Bound user-driven due-date changes to a near-overdue, capped, one-shot extension. */
  due_on_extension?: DueOnExtensionSpec;
  evidence_required?: EvidenceRequiredSpec;
  /** `status.default` — whether the step starts active (true) or dormant (false). */
  status?: { default: boolean };
  /** `state.default` — initial lifecycle state (defaults to "open"). */
  state?: { default: StepStateValue };
  comments_required?: CommentsRequiredSpec;
  /**
   * Flags the step for AI review of what is submitted on it (evidence against
   * `evidence_required.evaluation_criterion`). Advisory: the engine stores and
   * draws it, and gates nothing on it.
   */
  ai_review?: boolean;
  /** Days after which a completed step is archived/locked (0 = immediately). */
  completed_on_delta?: { default: number };
  /** When a step that starts completed was completed: a record migrated
   * from elsewhere. Only valid with `state.default: "completed"`. */
  completed_at?: { default: string };
  /** Evidence the step starts with (a migrated record); the actor defaults
   * to the step's first holder. */
  evidence?: { default: Array<{ ref: string; at?: string; actor?: string }> };
  assignee?: AssigneeSpec;
  /** Audit trail of edits made to this template (append-only). */
  changes?: unknown[];
}

/**
 * Allowed step-state transitions, `from` → list of legal `to` values.
 * Declaring it makes the engine reject any other transition at the API
 * boundary (422) instead of applying it and leaving authors to compensate
 * after the fact. Omit for the permissive default (any transition allowed).
 * A declared `from` with an empty list makes that state terminal.
 */
export type TransitionMatrix = Partial<Record<StepStateValue, StepStateValue[]>>;

export interface InitBlock {
  /** Instantiate only for tasks matching this query. Omit = always. */
  condition?: MongoExpr | string;
  /** Default projection/filter applied to the task source. */
  apply?: { default: MongoExpr | string };
  start_id: string;
  steps: StepTemplate[];
  /**
   * Canonical linear ordering of step ids, for consumers that need a flat list
   * rather than the rule-driven graph — a UI checklist, or the linear
   * `workflows[]` projection the platform's schema stores. Optional: omit it and
   * the flat order is the order `steps` are declared in. A partial list is
   * allowed; any step not named keeps its declared position after the ones
   * that are. Ordering only — it never affects routing, which is `diff`'s job.
   */
  flatten_order?: string[];
  transitions?: TransitionMatrix;
  /**
   * Declares when the instance is finished, in the same shape as a rule
   * `guard`: terminal once every step matching `selector` matches `all`.
   * The engine only evaluates the author's definition — it has no built-in
   * notion of which states mean "done". Surfaces as `instance.terminal`.
   */
  terminal_when?: GroupGuard;
}

// ── diff ────────────────────────────────────────────────────────────────────

export type SelectorRule = 'forAll' | 'first' | 'firstN' | 'group' | 'single';

export interface Selector {
  rule: SelectorRule;
  /** Required for firstN. */
  n?: number;
  /** Required for group/single: narrows the candidate steps. */
  group_selector?: MongoExpr;
}

/** Condition on a step property: either a live query, or a before→after transition. */
export type StepCondition =
  | { $condn: MongoExpr | string }
  | { $delta: { before: unknown; after: unknown } };

/**
 * Keys are step property paths (the spec writes them as "step$<property>",
 * e.g. "step$status"); the engine also accepts bare property names.
 */
export type DiffCondition = Record<string, StepCondition>;

/**
 * A value to set: deterministic `value`, gated by optional `$condn`
 * (only set when the query matches the target step), with `prompt` as the
 * AI fallback when `value` is absent.
 */
export interface SetExpr {
  $condn?: MongoExpr | string;
  prompt?: string;
  value?: unknown;
}

export type SettableProperty =
  | 'status'
  | 'state'
  /** Author-stamped; `{ "value": { "$delta": {} } }` resolves to "now". */
  | 'completed_at'
  | 'due_on'
  | 'assignee'
  | 'completed_on_delta';

export interface InternalAction {
  /** 'self' mutates the step that matched; 'other' mutates steps matching other_selector. */
  scope: 'self' | 'other';
  other_selector?: MongoExpr;
  set: Partial<Record<SettableProperty, SetExpr>>;
}

export interface EmailAction {
  recipients: OrResolution<DirectoryQuery>;
  subject?: SetExpr;
  body?: SetExpr;
  attachments?: { $generate?: string; $search?: string };
}

export interface AgentAction {
  _id: string;
  name: string;
  prompt: string;
  /** Arbitrary JSON state handed to the agent. */
  state?: unknown;
}

export interface ExternalAction {
  email?: EmailAction;
  agent?: AgentAction[];
}

/**
 * Universal (for-all) guard within one instance: after the rule's condition
 * matches, the rule fires only if EVERY step matching `selector` also matches
 * `all` (and at least one step matches `selector`). This is how aggregate
 * gates like "all maker/checker chains approved" are expressed.
 */
export interface GroupGuard {
  selector: MongoExpr;
  all: MongoExpr;
  /**
   * Quorum: fire once at least this many selected steps match `all`, instead
   * of requiring every one of them. `2` with a 3-reviewer selector is
   * "2-of-3". Omit for the universal (all-must-match) default.
   */
  min_matching?: number;
}

/**
 * Cross-instance (cohort) guard. A rule carrying `cohort_guard` is NOT run by
 * the normal per-instance diff pass; it is re-evaluated whenever any instance
 * sharing the same `task[join_on]` value changes. The guard passes when every
 * step matching `steps` across all cohort instances (filtered by `instances`,
 * excluding the watching instance itself) matches `all` — and at least one
 * step matched. Conditions on such rules must use `$condn` (there is no
 * changed-step `$delta` context on the watching instance).
 */
export interface CohortGuard {
  /** Task property joining the cohort, e.g. "batch_id". */
  join_on: string;
  /** Filter over sibling instance documents (e.g. { workflow_id: "..." }). */
  instances?: MongoExpr;
  /** Selects the steps that make up the aggregate pool. */
  steps: MongoExpr;
  /** Every pooled step must match this for the guard to pass. */
  all: MongoExpr;
  /** Quorum over the pooled steps; omit for all-must-match. See GroupGuard. */
  min_matching?: number;
}

export interface DiffRule {
  /** Lower runs first. */
  priority: number;
  applicability: 'all' | 'query';
  /** Required when applicability === 'query'. */
  applicability_query?: SetExpr;
  selector: Selector;
  condition: DiffCondition;
  guard?: GroupGuard;
  cohort_guard?: CohortGuard;
  /**
   * Fire at most once per instance. Guards are stateless, so a quorum rule
   * fires again on every later approval and on every rework cycle — harmless
   * for `internal.set` (idempotent) but duplicating every email/agent
   * dispatch. Set this on rules with external side effects.
   */
  once?: boolean;
  action: {
    internal?: InternalAction;
    external?: ExternalAction;
  };
}

/**
 * Directory fields the platform sends with every user. A directory query may
 * always filter on these; a workflow cannot redeclare them.
 */
export const PLATFORM_USER_ATTRIBUTES = [
  'id',
  'organization_id',
  'email',
  'role',
  'department',
  'departments',
  'business_unit',
  'business_units',
  'reporting_managers',
  'employment_status_active',
  // three upstream grouping-id fields a person covers (kept verbatim: UPSTREAM.json kept_identifiers)
  'legal_entity_ids',
  'office_location_ids',
  'financial_product_ids',
] as const;

/**
 * A user attribute the workflow's directory queries may filter on, e.g.
 * `{ key: 'desk', options: ['north', 'south'] }` for a step assigned by
 * `{ desk: 'north' }`. The platform offers `options` as a drop-down on the
 * user account and sends the chosen value as a field of the directory user.
 */
export const USER_ATTRIBUTE_TYPES = ['choice', 'multi_choice', 'boolean', 'text'] as const;
export type UserAttributeType = (typeof USER_ATTRIBUTE_TYPES)[number];

export interface UserAttribute {
  /** Field name on the directory user, as queries spell it. */
  key: string;
  /** How a value is held and compared; `choice` when omitted. */
  type?: UserAttributeType;
  /** For `choice` / `multi_choice`: the only values a user may hold and a query may compare against. */
  options?: string[];
}

export interface WorkflowDSL {
  /**
   * The user attributes this workflow supports. When declared, a directory
   * query may name only these and PLATFORM_USER_ATTRIBUTES; a workflow that
   * omits the list keeps the unchecked behaviour.
   */
  user_attributes?: UserAttribute[];
  init: InitBlock;
  diff: DiffRule[];
}
